// static
bool StructTraits<::photos::mojom::Memory::DataView, ::photos::mojom::MemoryPtr>::Read(
    ::photos::mojom::Memory::DataView input,
    ::photos::mojom::MemoryPtr* output) {
  bool success = true;
  ::photos::mojom::MemoryPtr result(::photos::mojom::Memory::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadItemUrl(&result->item_url))
        success = false;
      if (success && !input.ReadCoverUrl(&result->cover_url))
        success = false;
  *output = std::move(result);
  return success;
}

