PhotosHandlerAsyncWaiter::PhotosHandlerAsyncWaiter(
    PhotosHandler* proxy) : proxy_(proxy) {}

PhotosHandlerAsyncWaiter::~PhotosHandlerAsyncWaiter() = default;

void PhotosHandlerAsyncWaiter::GetMemories(
    std::vector<MemoryPtr>* out_memories) {
  base::RunLoop loop;
  proxy_->GetMemories(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<MemoryPtr>* out_memories
,
             std::vector<MemoryPtr> memories) {*out_memories = std::move(memories);
            loop->Quit();
          },
          &loop,
          out_memories));
  loop.Run();
}

std::vector<MemoryPtr> PhotosHandlerAsyncWaiter::GetMemories(
    ) {
  std::vector<MemoryPtr> async_wait_result;
  GetMemories(&async_wait_result);
  return async_wait_result;
}

void PhotosHandlerAsyncWaiter::ShouldShowOptInScreen(
    bool* out_show_opt_in_screen) {
  base::RunLoop loop;
  proxy_->ShouldShowOptInScreen(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_show_opt_in_screen
,
             bool show_opt_in_screen) {*out_show_opt_in_screen = std::move(show_opt_in_screen);
            loop->Quit();
          },
          &loop,
          out_show_opt_in_screen));
  loop.Run();
}

bool PhotosHandlerAsyncWaiter::ShouldShowOptInScreen(
    ) {
  bool async_wait_result;
  ShouldShowOptInScreen(&async_wait_result);
  return async_wait_result;
}

